import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"Behandlings Muligheder","description":"","frontmatter":{},"headers":[],"relativePath":"behandlingsmuligheder.md","filePath":"behandlingsmuligheder.md"}`),a={name:`behandlingsmuligheder.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="behandlings-muligheder" tabindex="-1">Behandlings Muligheder <a class="header-anchor" href="#behandlings-muligheder" aria-label="Permalink to “Behandlings Muligheder”">​</a></h1><p>Som transpersoner i Danmark har vi ikke lige så mange muligheder som i nogle andre lande, men vi har stadig forskellige muligheder for at få hormonbehandling. De forskellige muligheder varierer i pris, tilgængelighed, og brugervenlighed. Her vil vi gå igennem dem og diskutere deres pros and cons.</p><h2 id="cki" tabindex="-1">CKI <a class="header-anchor" href="#cki" aria-label="Permalink to “CKI”">​</a></h2><p>Dette er den mest kendte mulighed og nok også en, du allerede har prøvet.</p><p>Der er tre forskellige CKI&#39;er. De ligger i Aalborg, Odense og København. Hver CKI er forskellig, og nogle er bedre end andre.</p><p>CKI Aalborg er generelt kendt for at være den bedste af de tre. Den har et ry for at have bedre personale, som behandler transpersoner bedre og hjælper dem med at få hormoner hurtigere. CKI Aalborg kan have lang ventetid, før man kan få sin første samtale, men når man først er i gang, tager det ikke urimeligt lang tid at blive godkendt til hormonbehandling. Hvis du vil starte hormoner hos CKI, vil jeg anbefale at få en henvisning til Aalborg.</p><p>CKI København har et ry for at behandle transpersoner meget dårligt, ofte stille ubehagelige spørgsmål, og for at det føles, som om man bliver afhørt af dem. Jeg ville holde mig langt fra dem.</p><p>CKI Odense er generelt ikke lige så dårlig som København, men den er ekstremt langsom. Mange oplever at vente i flere år, før deres sag bliver taget op på konference, og endnu længere, før de bliver godkendt til hormonbehandling.</p><p>Uanset hvilken du vælger, vil der være problemer hos CKI. CKI kan være en af de billigste måder at få hormonbehandling på, men det er også den mest langsomme og besværlige. Mange oplever lange ventelister, diskrimination og ubehagelige samtaler med de ansatte. På grund af disse ting vil jeg ikke anbefale CKI til de fleste. Hvis du har autisme eller psykiske lidelser som angst, OCD, depression, PTSD osv., er der stor chance for, at de vil afvise dig. Det oplever mange i hvert fald, og det er også det, jeg selv har oplevet.</p><p>Hvis du gerne vil i behandling ved CKI, kan det være en god idé at starte et forløb dér, mens du samtidig bruger en af de andre muligheder, indtil du bliver godkendt til hormonbehandling hos dem.</p><h2 id="private-klinikker" tabindex="-1">Private klinikker <a class="header-anchor" href="#private-klinikker" aria-label="Permalink to “Private klinikker”">​</a></h2><p>Private klinikker kan være en af de dyreste muligheder du har, men det er også en af de bedste du har. Private klinikker giver dig ofte hurtig adgang til behandling, forskellige former af hormoner (gel, spray, piller, etc.) og giver dig EU-gyldige recepter så du får hormonerne direkte fra et dansk apotek. Der er forskellige private klinikker som kan udskrive EU-gyldige recepter. Herunder er der en liste over de mest velkendte private klinikker:</p><ul><li><a href="https://www.imago.tg/" target="_blank" rel="noreferrer">Imago</a> - Imago er nok den mest velkendte EU privat klinik og tilbyder god behandling til en rimelig pris. Det er den klinik jeg ville anbefale til de fleste transpersoner.</li><li><a href="https://anne.health/" target="_blank" rel="noreferrer">Anne Health</a> - Anne Health er en ny privat klinik der er startet i England, men har indtil videre et positivt ry.</li><li><a href="https://www.hormonygender.dk/" target="_blank" rel="noreferrer">Hormony Gender</a> - Hormony Gender er den eneste danske privat klinik der tilbyder hormonbehandling til transpersoner og er også relativt ny. Hormony Gender er ikke anbefalet på grund af deres lange og meget dyre afklarende forløb.</li><li><a href="https://www.gendergp.com/" target="_blank" rel="noreferrer">GenderGP</a> - GenderGP er ikke anbefalet. Det plejede at være en af de mest populære klinikker men det er det absolut ikke længere. De har forfærdelig service, er næsten umulige at komme i kontakt med og giver dårlig, nogle gange helt forkert behandling. Jeg ville holde mig langt væk fra GenderGP.</li></ul><h2 id="diy" tabindex="-1">DIY <a class="header-anchor" href="#diy" aria-label="Permalink to “DIY”">​</a></h2><p>Hvis du ikke har råd eller lyst til at bruge en privat klinik, er din sidste mulighed DIY. Men der er mange forskellige typer af DIY. Den mest almindelige og billigeste er injektioner. Injektioner er den bedste mulighed for de fleste. De kan tages hver 7.-10. dag, hvilket betyder at en enkelt flaske kan vare i lang tid. De er også bedre til at hæmme virkningen af testosteron så man kan lave monoterapi, hvilket vil sige, at man ikke behøver at tage antiandrogener. På grund af dette er injektioner en billig og effektiv løsning.</p><p>For mange kan injektioner dog være skræmmende eller ubehagelige. Heldigvis er der også andre løsninger. Nogle af de sælgere, som sælger injektioner, sælger nemlig også transdermal østrogen. Ofte i formen af spray eller gel. Dette er som regel dyrere end injektioner, men hvis du har råd til det, kan det være et fantastisk alternativ til injektioner. Man kan også købe østrogenpiller, men disse kan også blive rimelig dyre, og har for nogen ikke lige så god effekt, og kan give højere risiko for blodprop.</p><p>Det største problem ved DIY er, at det kan være virkelig svært at finde en sælger som ikke er solgt ud. Dette er desværre bare fordi der er mange som har brug for hormoner og ikke så mange der laver dem, og dem som laver det er ikke store firmaer men bare nogle normale personer som laver det i deres hjem. Derfor er det vigtigt altid at holde øje med hvem der har noget på lager. Du kan eventuelt bruge sider som <a href="https://valerie.vg/" target="_blank" rel="noreferrer">valerie.vg</a> eller <a href="https://diyhrt.coffee/" target="_blank" rel="noreferrer">diyhrt.coffee</a> til at holde styr på hvem der sælger det du har brug for.</p><p>Hvis tilgængelighed bliver et så stort problem at vi slet ikke kan købe hormoner nogen steder, er der stadig en mulighed tilbage, homebrewing. Altså at lave dem selv. Det vil jeg snakke mere om i homebrewing guiden.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};